// Keep rows with valid coordinates; radius defaults to 10 km, capped at 50.
const out = [];
for (const item of $input.all()) {
  const r = item.json;
  const lat = parseFloat(String(r['Latitude'] ?? '').replace(',', '.'));
  const lon = parseFloat(String(r['Longitude'] ?? '').replace(',', '.'));
  if (!Number.isFinite(lat) || !Number.isFinite(lon) || Math.abs(lat) > 90 || Math.abs(lon) > 180) continue;
  let radius = parseFloat(String(r['Radius km'] ?? '').replace(',', '.'));
  if (!Number.isFinite(radius) || radius <= 0) radius = 10;
  radius = Math.min(radius, 50);
  out.push({ json: {
    row_number: r.row_number,
    site: r['Site'] || `${lat}, ${lon}`,
    lat, lon, radius_km: radius,
    date_from: $now.minus({ days: 30 }).toFormat('yyyy-MM-dd'),
  } });
}
return out;

// One summary per row: counts by category and the three most important events.
const rows = $('Check the row').all();
const stats = $('Count events by category').all();

return $input.all().map((item, i) => {
  const row = rows[i].json;
  const s = stats[i].json.structuredContent?.result ?? {};
  const buckets = (s.buckets ?? []).slice().sort((a, b) => b.count - a.count);
  const events = item.json.structuredContent?.result?.events ?? [];
  const top = events.map((e) => {
    const src = (e.sources ?? [])[0]?.url;
    return `${(e.occurred_at ?? '').slice(0, 10)}: ${e.description}${src ? ` (${src})` : ''}`;
  });
  return { json: {
    row_number: row.row_number,
    'Events (30 days)': s.total ?? 0,
    'Main categories': buckets.slice(0, 3).map((b) => `${b.label} ${b.count}`).join(', ') || 'none found',
    'Top events': top.join('\n') || 'No events found in the news for this area. That does not prove it was calm.',
    'Checked on': $now.toFormat('yyyy-MM-dd'),
  } };
});
